1: /**
2:  * Programmatic Public-role hardening (ADR-002 §4.1, US-01 §4.5, US-02 §4.4).
3:  *
4:  * The Angular application is fully anonymous and read-only: it never sends an
5:  * `Authorization` header and no API token exists. The only browser access path
6:  * is therefore the users-permissions `Public` role, which must keep exactly the
7:  * six read-only actions listed below and nothing else.
8:  *
9:  * The configuration is a full replacement, not an addition: any other
10:  * permission attached to `Public` (including `api::*`, `plugin::users-permissions.*`
11:  * and `plugin::upload.*` entries) is revoked, so the default is denial.
12:  */
13: import type { Core } from '@strapi/strapi';
14: 
15: export const PUBLIC_READ_ACTIONS = [
16:   'api::form-field.form-field.find',
17:   'api::form-field.form-field.findOne',
18:   'api::country-config.country-config.find',
19:   'api::country-config.country-config.findOne',
20:   'api::insurance-plan.insurance-plan.find',
21:   'api::insurance-plan.insurance-plan.findOne',
22: ] as const;
23: 
24: interface RoleRecord {
25:   readonly id: number;
26:   readonly type: string | null;
27: }
28: 
29: interface PermissionRecord {
30:   readonly id: number;
31:   readonly action: string;
32: }
33: 
34: const PUBLIC_ROLE_TYPE = 'public';
35: 
36: export const configurePublicRolePermissions = async (strapi: Core.Strapi): Promise<void> => {
37:   const publicRole = (await strapi.db.query('plugin::users-permissions.role').findOne({
38:     where: { type: PUBLIC_ROLE_TYPE },
39:   })) as RoleRecord | null;
40: 
41:   if (!publicRole) {
42:     // Fail closed: without the Public role the read-only posture cannot be verified.
43:     throw new Error(
44:       '[bootstrap] users-permissions Public role was not found; refusing to start with an unverified permission set.'
45:     );
46:   }
47: 
48:   const permissionStore = strapi.db.query('plugin::users-permissions.permission');
49: 
50:   const currentPermissions = (await permissionStore.findMany({
51:     where: { role: { id: publicRole.id } },
52:   })) as PermissionRecord[];
53: 
54:   const allowlist = new Set<string>(PUBLIC_READ_ACTIONS);
55:   const keptActions = new Set<string>();
56:   const permissionsToRevoke: PermissionRecord[] = [];
57: 
58:   for (const permission of currentPermissions) {
59:     // Keep the first record per allowed action; revoke everything else,
60:     // including duplicates of an allowed action.
61:     if (!allowlist.has(permission.action) || keptActions.has(permission.action)) {
62:       permissionsToRevoke.push(permission);
63:       continue;
64:     }
65: 
66:     keptActions.add(permission.action);
67:   }
68: 
69:   for (const permission of permissionsToRevoke) {
70:     await permissionStore.delete({ where: { id: permission.id } });
71:   }
72: 
73:   const permissionsToGrant = PUBLIC_READ_ACTIONS.filter((action) => !keptActions.has(action));
74: 
75:   for (const action of permissionsToGrant) {
76:     await permissionStore.create({ data: { action, role: publicRole.id } });
77:   }
78: 
79:   strapi.log.info(
80:     `[bootstrap] Public role locked to ${PUBLIC_READ_ACTIONS.length} read-only actions ` +
81:       `(revoked: ${permissionsToRevoke.length}, granted: ${permissionsToGrant.length}).`
82:   );
83: };

